from lib15 import *
# ===== Corp (M16): Voss / Corvin Funds, EcoStay Resorts bonds (principal-principal, board independence, ESG in fixed income) [from marker-esg] =====
body="""Hannah Voss, CFA, is a fixed-income analyst for the Corvin Funds. Her supervisor asks her to identify ESG factors and value the corporate bonds of EcoStay Resorts, a publicly traded boutique resort company. Voss notes that EcoStay is a "green resort" company that prioritizes sustainability and has successfully reduced water and energy usage at its resorts. The founding family owns 52% of the outstanding shares. Each ownership share has equivalent voting rights. The board of directors of EcoStay consists of 14 members, with independent CEO and chairperson roles. The board includes one independent member and two women, and three members (about 21%) have experience in the resort industry.
EcoStay has historically had a high labor turnover rate. Most of its workforce are paid at or near the minimum wage, and the company offers no health benefits. Voss and her supervisor discuss how EcoStay will be affected by the expected passage of legislation raising the minimum wage and growing pressure to offer benefits. Voss integrates ESG factors in the investment valuation of EcoStay's corporate bonds."""
add('M16','Corporate Issuers',body,[
 q("The potential conflict between or among shareholders and managers of EcoStay can best be described as:",["a principal-agent problem.","a principal-principal problem.","voting caps."],1,
  ["Incorrect. The principal-agent problem arises with dispersed ownership and dispersed voting rights (weak shareholders, strong managers).","Correct. The family owns 52% of the shares and each share has equal voting rights, so ownership and voting power are concentrated: the conflict is between controlling and minority shareholders.","Incorrect. Voting caps are legal restrictions on the votes of large holders (concentrated ownership with dispersed voting rights); they are not a conflict."],
  ["The founding family owns 52% of the outstanding shares.","Each ownership share has equivalent voting rights."],"Controlling shareholder + one share one vote → principal-principal (controlling vs minority); dispersed ownership → principal-agent.",fixed=False),
 q("EcoStay's corporate governance risk is increased by:",["the low percentage of independent board members.","CEO duality.","family control."],0,
  ["Correct. Only one of the 14 board members is independent, below the usual 20%-50% minimum ratio.","Incorrect. The CEO and chairperson roles are independent of each other, so there is no CEO duality (a sign of good governance).","Incorrect. Family control lowers principal-agent risk; it is not the main governance risk here."],
  ["The board includes one independent member","independent CEO and chairperson roles"],"Governance risk: few independent directors raises risk; separate CEO/chair roles reduce it.",fixed=False),
 q("The security analysis of EcoStay is most likely focused on:",["adjusting the discount rate.","identifying potential opportunities.","mitigating downside risk."],2,
  ["Incorrect. Adjusting the discount rate belongs to equity analysis; in fixed income the credit spread or CDS is adjusted.","Incorrect. Identifying opportunities belongs to equity analysis.","Correct. In fixed-income analysis ESG integration focuses on mitigating downside risk."],
  ["fixed-income analyst","corporate bonds of EcoStay Resorts"],"ESG in fixed income: downside risk; in equity: opportunities and downside risk, discount rate adjustment.",fixed=False),
 q("After integrating the ESG factors, the credit spread on EcoStay's bonds is most likely to:",["decrease.","increase.","remain unchanged."],1,
  ["Incorrect. Higher ESG risk does not lower the spread.","Correct. Weak governance (one independent director, little diversity, little industry experience) and social risk (low pay, no benefits, rising minimum wage) raise costs and cash flow risk, so the credit spread rises.","Incorrect. The identified ESG risks affect the valuation, so the spread does not stay unchanged."],
  ["Most of its workforce are paid at or near the minimum wage","legislation raising the minimum wage"],"Higher ESG risk → higher credit spread (lower bond value); better ESG → lower spread.",fixed=False),
])
